SELECT tb_purchase_parts_order.*, DATE_FORMAT(tb_purchase_parts_order.create_time, '%Y-%m-%d') AS order_date, COALESCE((SELECT SUM(d.need_number) FROM tb_purchase_parts_order_detail d WHERE d.order_id = tb_purchase_parts_order.id AND IFNULL(d.is_deleted, 0) = 0), 0) AS total_need_qty, CASE WHEN TRIM(IFNULL(tb_purchase_parts_order.delivery_status, '')) = '已交付' THEN COALESCE((SELECT SUM(d.need_number) FROM tb_purchase_parts_order_detail d WHERE d.order_id = tb_purchase_parts_order.id AND IFNULL(d.is_deleted, 0) = 0), 0) ELSE 0 END AS total_shipped_qty, s.SUPPLIER_NAME AS supplier_name,
( SELECT CASE WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 0 THEN 1 ELSE 0 END) THEN 0 WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 20 THEN 1 ELSE 0 END) THEN 20 WHEN SUM(CASE WHEN d.supplier_order_status IN (25, 30) THEN 1 ELSE 0 END) = COUNT(*) AND COUNT(*) > 0 THEN 30 ELSE 21 END FROM tb_purchase_parts_order_detail d WHERE d.order_id = tb_purchase_parts_order.id AND IFNULL(d.is_deleted, 0) = 0 ) AS supplier_order_status FROM tb_purchase_parts_order LEFT JOIN tb_contract_supplier s ON tb_purchase_parts_order.supplier_id = s.ID WHERE IFNULL(tb_purchase_parts_order.is_deleted, 0) = 0 AND tb_purchase_parts_order.order_status = 1
AND tb_purchase_parts_order.supplier_id = #{supplierId}
AND (
tb_purchase_parts_order.order_no LIKE CONCAT('%', #{on}, '%')
)
AND ( SELECT CASE WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 0 THEN 1 ELSE 0 END) THEN 0 WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 20 THEN 1 ELSE 0 END) THEN 20 WHEN SUM(CASE WHEN d.supplier_order_status IN (25, 30) THEN 1 ELSE 0 END) = COUNT(*) AND COUNT(*) > 0 THEN 30 ELSE 21 END FROM tb_purchase_parts_order_detail d WHERE d.order_id = tb_purchase_parts_order.id AND IFNULL(d.is_deleted, 0) = 0 ) IN
#{status}
AND s.SUPPLIER_NAME LIKE CONCAT('%', #{supplierName}, '%')
AND tb_purchase_parts_order.order_time >= CONCAT(#{startDate}, ' 00:00:00')
AND tb_purchase_parts_order.order_time <= CONCAT(#{endDate}, ' 23:59:59')
AND tb_purchase_parts_order.require_attr = #{requireAttr}
ORDER BY
tb_purchase_parts_order.order_no ${sortOrder} tb_purchase_parts_order.create_time ${sortOrder} s.SUPPLIER_NAME ${sortOrder} tb_purchase_parts_order.id DESC
ORDER BY tb_purchase_parts_order.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM tb_purchase_parts_order LEFT JOIN tb_contract_supplier s ON tb_purchase_parts_order.supplier_id = s.ID WHERE IFNULL(tb_purchase_parts_order.is_deleted, 0) = 0 AND tb_purchase_parts_order.order_status = 1
AND tb_purchase_parts_order.supplier_id = #{supplierId}
AND (
tb_purchase_parts_order.order_no LIKE CONCAT('%', #{on}, '%')
)
AND ( SELECT CASE WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 0 THEN 1 ELSE 0 END) THEN 0 WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 20 THEN 1 ELSE 0 END) THEN 20 WHEN SUM(CASE WHEN d.supplier_order_status IN (25, 30) THEN 1 ELSE 0 END) = COUNT(*) AND COUNT(*) > 0 THEN 30 ELSE 21 END FROM tb_purchase_parts_order_detail d WHERE d.order_id = tb_purchase_parts_order.id AND IFNULL(d.is_deleted, 0) = 0 ) IN
#{status}
AND s.SUPPLIER_NAME LIKE CONCAT('%', #{supplierName}, '%')
AND tb_purchase_parts_order.order_time >= CONCAT(#{startDate}, ' 00:00:00')
AND tb_purchase_parts_order.order_time <= CONCAT(#{endDate}, ' 23:59:59')
AND tb_purchase_parts_order.require_attr = #{requireAttr}

SELECT COUNT(DISTINCT o.id) AS order_count, COALESCE(SUM(d.need_number), 0) AS total_need_qty, COALESCE(SUM(CASE WHEN d.supplier_order_status = 0 THEN d.need_number ELSE 0 END), 0) AS pending_confirm_qty, COALESCE(SUM(IFNULL(d.delivery_number, 0)), 0) AS total_shipped_qty, COALESCE(SUM( COALESCE((SELECT SUM(a.ship_qty) FROM tb_srm_asn a INNER JOIN tb_srm_asn_order ao ON a.id = ao.asn_id WHERE ao.order_id = o.id AND IFNULL(a.is_deleted, 0) = 0 AND a.status != 'SHIPPED'), 0) ), 0) AS pending_ship_qty, COALESCE(SUM(CASE WHEN TRIM(IFNULL(o.delivery_status, '')) != '已交付' THEN d.need_number ELSE 0 END), 0) AS remaining_qty FROM tb_purchase_parts_order o INNER JOIN tb_purchase_parts_order_detail d ON o.id = d.order_id WHERE IFNULL(o.is_deleted, 0) = 0 AND IFNULL(d.is_deleted, 0) = 0 AND o.order_status = 1 AND o.require_attr = '订单'
AND o.supplier_id = #{supplierId}
AND (
o.order_no LIKE CONCAT('%', #{on}, '%')
)
AND (
d.parts_number LIKE CONCAT('%', #{pn}, '%')
)
AND ( SELECT CASE WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 0 THEN 1 ELSE 0 END) THEN 0 WHEN COUNT(*) = SUM(CASE WHEN d.supplier_order_status = 20 THEN 1 ELSE 0 END) THEN 20 WHEN SUM(CASE WHEN d.supplier_order_status IN (25, 30) THEN 1 ELSE 0 END) = COUNT(*) AND COUNT(*) > 0 THEN 30 ELSE 21 END FROM tb_purchase_parts_order_detail dd WHERE dd.order_id = o.id AND IFNULL(dd.is_deleted, 0) = 0 ) IN
#{status}
AND o.order_time >= CONCAT(#{startDate}, ' 00:00:00')
AND o.order_time <= CONCAT(#{endDate}, ' 23:59:59')

SELECT d.id AS id, d.order_id, o.order_no, COALESCE(NULLIF(pm.EXTERNAL_PART_NO, ''), d.parts_number) AS parts_no, pm.CHINESE_NAME AS parts_name, s.SUPPLIER_NAME AS supplier_name, d.need_number AS order_qty, IFNULL(d.delivery_number, 0) AS shipped_qty, COALESCE((SELECT SUM(s.shipped_qty) FROM tb_srm_asn_line s WHERE s.split_line_id IN (SELECT id FROM tb_srm_po_split_line WHERE detail_id = d.id)), 0) + COALESCE((SELECT SUM(a.ship_qty) FROM tb_srm_asn a WHERE a.order_detail_id = d.id AND IFNULL(a.is_deleted, 0) = 0 AND a.status != 'SHIPPED' AND a.ship_qty IS NOT NULL), 0) AS pending_ship_qty, IFNULL(d.need_number, 0) - IFNULL(d.delivery_number, 0) AS remaining_qty, d.need_date, o.address AS ship_to_address, d.storage_name AS ship_to_plant, d.storage_name AS storage_name, d.supplier_order_status, DATE_FORMAT(o.create_time, '%Y-%m-%d') AS order_date FROM tb_purchase_parts_order_detail d INNER JOIN tb_purchase_parts_order o ON d.order_id = o.id LEFT JOIN tb_parts_maint pm ON d.parts_number = pm.PARTS_NO AND pm.IS_DELETED = 0 LEFT JOIN tb_contract_supplier s ON o.supplier_id = s.ID WHERE IFNULL(d.is_deleted, 0) = 0 AND IFNULL(o.is_deleted, 0) = 0 AND o.order_status = 1
AND o.supplier_id = #{supplierId}
AND (
o.order_no LIKE CONCAT('%', #{on}, '%')
)
AND (
d.parts_number LIKE CONCAT('%', #{pn}, '%')
)
AND d.supplier_order_status = #{supplierOrderStatus}
AND o.create_time >= CONCAT(#{startDate}, ' 00:00:00')
AND o.create_time <= CONCAT(#{endDate}, ' 23:59:59')
AND o.require_attr = #{requireAttr}
ORDER BY
COALESCE(NULLIF(pm.EXTERNAL_PART_NO, ''), d.parts_number) ${sortOrder} o.order_no ${sortOrder} d.need_date ${sortOrder} o.create_time ${sortOrder} o.create_time DESC, o.order_no DESC, d.id ASC
ORDER BY o.create_time DESC, o.order_no DESC, d.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM tb_purchase_parts_order_detail d INNER JOIN tb_purchase_parts_order o ON d.order_id = o.id WHERE IFNULL(d.is_deleted, 0) = 0 AND IFNULL(o.is_deleted, 0) = 0 AND o.order_status = 1
AND o.supplier_id = #{supplierId}
AND (
o.order_no LIKE CONCAT('%', #{on}, '%')
)
AND (
d.parts_number LIKE CONCAT('%', #{pn}, '%')
)
AND d.supplier_order_status = #{supplierOrderStatus}
AND o.create_time >= CONCAT(#{startDate}, ' 00:00:00')
AND o.create_time <= CONCAT(#{endDate}, ' 23:59:59')
AND o.require_attr = #{requireAttr}

